using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace Hryushki {
public partial class MainWindow {
 SyncService sync;Timer syncTimer;bool syncBusy,applyingSync;string syncStatus="Тестовая база. Войдите и подключите её к облаку.";
 void InitSync(){sync=new SyncService(appRoot);syncTimer=new Timer{Interval=60000};syncTimer.Tick+=async(s,e)=>await SyncNow(false);syncTimer.Start();store.Saved+=async()=>{if(!applyingSync&&!syncBusy){await Task.Delay(1200);await SyncNow(false);}};FormClosed+=(s,e)=>syncTimer.Dispose();}
 async Task SyncNow(bool manual){if(syncBusy||!sync.Signed||SyncModel.Obj(store.Data,"_sync")==null||OwnedForms.Length>0)return;syncBusy=true;string path=store.PathName;try{syncStatus="Обмен с облаком…";var q=SyncModel.Prepare(store.Data,sync.Owner);var reply=await sync.Exchange(q.Changes);while(!IsDisposed&&OwnedForms.Length>0)await Task.Delay(200);if(IsDisposed||store.PathName!=path)return;applyingSync=true;store.Save(SyncModel.Merge(store.Data,q,reply,sync.Owner));syncStatus=J.Rows(SyncModel.Obj(store.Data,"_sync"),"conflicts").Count>0?"Конфликт: выберите вариант в разделе «Синхронизация»":"Синхронизировано: "+DateTime.Now.ToString("HH:mm:ss");RefreshPage();}catch(Exception ex){syncStatus="Не синхронизировано: "+ex.GetBaseException().Message;if(manual)MessageBox.Show(this,syncStatus,"Синхронизация");}finally{applyingSync=false;syncBusy=false;if(!IsDisposed)status.Text=syncStatus;}}
 void SyncPage(){var l=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};body.Controls.Add(l);var info=Theme.Label("ТЕСТОВАЯ СИНХРОНИЗАЦИЯ\n"+(sync.Signed?sync.Email:"Вход не выполнен")+"\n"+syncStatus,11,true);info.Size=new Size(780,100);l.Controls.Add(info);var warning=Theme.Label("Рабочие приложения и их базы не подключаются автоматически. Используйте отдельный тестовый аккаунт.\nОбмениваются операции, товары и материалы. Вход — один аккаунт на ПК и телефоне.\nАвтообмен: после изменения и каждые 60 секунд, пока программа открыта. Пароль не сохраняется.",10);warning.Size=new Size(800,95);l.Controls.Add(warning);
 var login=Theme.Button("Войти",()=>{} ,true);login.Click+=async(s,e)=>{if(syncBusy)return;string email="",password="";using(var f=new EditorDialog("Вход в тестовую синхронизацию")){var a=f.TextField("Email тестового аккаунта",sync.Email);var b=f.TextField("Пароль аккаунта (не пароль БД)","");b.UseSystemPasswordChar=true;f.SaveAction=()=>{email=a.Text.Trim();password=b.Text;};if(f.ShowDialog(this)!=DialogResult.OK)return;}login.Enabled=false;try{await sync.Login(email,password);syncStatus="Вход выполнен. Подключите пустую базу.";RefreshPage();}catch(Exception ex){MessageBox.Show(this,ex.GetBaseException().Message,"Вход");}finally{password="";if(!login.IsDisposed)login.Enabled=true;}};l.Controls.Add(login);
 l.Controls.Add(Theme.Button("Подключить базу",()=>Try(()=>{if(!sync.Signed)throw new Exception("Сначала войдите");if(SyncModel.Obj(store.Data,"_sync")==null&&new[]{"operations","products","materials"}.Any(k=>J.Rows(store.Data,k).Count>0))throw new Exception("Для первого подключения нужна пустая тестовая база. Не подключайте рабочую бухгалтерию.");store.Save(SyncModel.Attach(store.Data,sync.Owner));syncStatus="Подключено. Выполняется первый обмен.";RefreshPage();})));
 var now=Theme.Button("Обмен сейчас",()=>{});now.Click+=async(s,e)=>await SyncNow(true);l.Controls.Add(now);
 l.Controls.Add(Theme.Button("Выйти",()=>Try(()=>{if(syncBusy)throw new Exception("Дождитесь завершения обмена");sync.Logout();syncStatus="Вы вышли. Локальные записи сохранены.";RefreshPage();})));
 var meta=SyncModel.Obj(store.Data,"_sync");if(meta!=null){var conflicts=J.Rows(meta,"conflicts");for(int i=0;i<conflicts.Count;i++){int index=i;var r=conflicts[i];string caption=J.S(r,"kind")+" · "+J.S(SyncModel.Obj(r,"data"),"name",J.S(SyncModel.Obj(r,"data"),"item",J.S(r,"key")));var label=Theme.Label("Конфликт: "+caption+"\nНА УСТРОЙСТВЕ: "+J.Dump(SyncModel.Obj(r,"local"))+"\nВ ОБЛАКЕ: "+J.Dump(SyncModel.Obj(r,"data")),9);label.Size=new Size(800,140);l.Controls.Add(label);l.Controls.Add(Theme.Button("Взять из облака",()=>Try(()=>{store.Save(SyncModel.Resolve(store.Data,index,true));RefreshPage();})));l.Controls.Add(Theme.Button("Оставить местное",()=>Try(()=>{store.Save(SyncModel.Resolve(store.Data,index,false));RefreshPage();})));}}
 }
}
}
